'use strict';
let lang='zh';
try{if(localStorage.getItem('europe-history-atlas-language')==='en')lang='en';}catch{}
const L=(zh,en)=>lang==='en'?en:zh;
const COUNTRIES_EN={'英国':'United Kingdom','希腊':'Greece','意大利':'Italy','德国':'Germany','土耳其':'Türkiye','丹麦':'Denmark','捷克':'Czechia','波兰':'Poland','西班牙':'Spain','俄罗斯':'Russia','奥地利':'Austria','匈牙利':'Hungary','法国':'France','葡萄牙':'Portugal','荷兰':'Netherlands','爱尔兰':'Ireland','瑞典':'Sweden','挪威':'Norway','瑞士':'Switzerland','比利时':'Belgium','罗马尼亚':'Romania','爱沙尼亚':'Estonia','塞尔维亚':'Serbia','保加利亚':'Bulgaria','立陶宛':'Lithuania','克罗地亚':'Croatia','斯洛文尼亚':'Slovenia','乌克兰':'Ukraine','拉脱维亚':'Latvia','马耳他':'Malta','冰岛':'Iceland'};
const countryLabel=c=>lang==='en'?c.split(' / ').map(x=>COUNTRIES_EN[x]).join(' / '):c;
const RELATIONS_EN={'时代见证':'Evidence of the period','直接关联':'Direct connection','跨时代遗产':'Multiple periods','同期对照':'Contemporary comparison','历史关联':'Historical connection'};
const ERA_EN={
prehistory:['Palaeolithic–c. 2000 BCE','Prehistoric life, art and settlements','How did communities organise themselves?','Before writing, art, settlements, tombs and ceremonial places offer evidence of social life. Farming brought new forms of settlement, but regions developed at different times.','Settled societies developed more complex urban and political organisations.'],
bronze:['c. 3000–1100 BCE','Bronze Age palaces and citadels','How did palaces organise trade and power?','Aegean palaces, citadels and tombs record early complex societies. Minoan and Mycenaean cultures exchanged ideas but organised political life differently.','After palatial systems declined, city-states gradually emerged under new social conditions.'],
greece:['c. 800–146 BCE','City-states and the Greek world','Why did shared culture not create a single state?','Competing cities coexisted with shared sanctuaries. Civic politics, maritime exchange and the Hellenistic world shaped later Mediterranean history.','Rome gradually integrated these competing regions into a larger political network.'],
rome:['c. 509 BCE–395 CE','Roman Republic and Empire','What connected a vast territory?','Roads, cities, law and armies connected the Mediterranean. Frontiers were both military boundaries and places of trade and migration.','Shifts in imperial centres and religion contributed to diverging eastern and western political trajectories.'],
late:['c. 300–700','Rome transformed and continued','Did Rome end when the western imperial office disappeared?','Christianity transformed public space and expressions of power. New kingdoms emerged in the west while the Eastern Roman Empire continued; Ravenna preserves evidence of successive regimes.','Eastern Rome endured while new relationships between rulers and churches developed in western Europe.'],
carolingian:['c. 750–1000','Carolingians, Vikings and early kingdoms','Who could inherit Rome’s imperial ideal?','Carolingian rulers and churches constructed authority together. Charlemagne was crowned in 800; the empire was divided in 843. Northern societies also changed through kingship and Christianisation.','Multiple political centres developed, with churches, rulers and cities competing for power.'],
medieval:['c. 1000–1400','Churches, kingdoms and trading cities','Did power belong only to kings?','Cathedrals, universities, merchant cities and maritime trade shaped medieval Europe. Kingdoms and cities developed along different regional paths.','Urban wealth and knowledge networks helped create conditions for artistic and intellectual change.'],
frontiers:['c. 711–1600','Islamic, Byzantine and Ottoman worlds','How did borders become zones of exchange?','War, changes of rule and cultural exchange coexisted in Iberia and the eastern Mediterranean. Constantinople in 1453 and Granada in 1492 mark different historical trajectories.','These developments overlapped the Renaissance and maritime expansion rather than forming a single sequence.'],
renaissance:['c. 1400–1600','Renaissance and maritime expansion','How did urban wealth change views of the world?','Italian patronage and renewed study of antiquity encouraged artistic change. Iberian maritime expansion connected distant regions while bringing conquest, colonisation and exploitation.','New knowledge, commercial wealth and religious disputes challenged established authority.'],
reformation:['1517–1648','Reformation and political division','Why did belief reshape political boundaries?','The Reformation involved faith, communication and political authority. War and negotiation changed European order; 1648 was important, but modern states did not appear overnight.','Dynastic states continued to consolidate power, while commercial republics developed different institutions.'],
dynasties:['c. 1600–1789','Dynasties, republics and Enlightenment','Who controlled cities and states?','Courts, merchant elites and imperial capitals embodied different forms of power. Palaces and urban plans organised social hierarchies and economic activity as well as taste.','Enlightenment ideas, financial crises and social conflict contributed to the age of revolutions.'],
revolution:['1789–1871','Revolutions and nation-states','How did subjects become citizens?','The French Revolution, Napoleonic wars and subsequent settlements changed ideas of sovereignty. Nationalism, empires and liberalism competed; there was no single path to modernity.','Industrialisation accelerated social change and increased states’ capacity to mobilise populations.'],
industry:['c. 1750–1914','Industrialisation and imperial societies','How did factories change everyday life?','Coal, iron, machinery and transport transformed work and cities. Industrial growth was intertwined with colonial systems; wealth and social costs need to be considered together.','Mass society, technology and political conflict carried into the twentieth century.'],
war:['1914–1945','World wars and the crisis of modernity','Why did modern societies turn to mass destruction?','War, dictatorship, persecution and the Holocaust must be considered alongside modern art and social experiments. Memorial visits centre victims’ experiences and historical responsibility.','Reconstruction, Cold War division and institutions of cooperation developed together.'],
postwar:['1945–present','Reconstruction, division and cooperation','How does Europe deal with shared history?','Rebuilding, the Cold War and European integration shaped postwar life. The EU is a cooperative institution of some European countries, not the whole continent or a reborn ancient empire.','Preservation, reconstruction and memory offer ways to continue exploring contemporary Europe.']
};
const PERIODS=[
{id:'pre',zh:'史前与青铜时代',en:'Prehistory & Bronze Age',dateZh:'文字出现以前；各地时间不同',dateEn:'Before written records; regional variation',eras:['prehistory','bronze']},
{id:'ancient',zh:'古代',en:'Antiquity',dateZh:'本图谱主要关注约前800—公元500',dateEn:'Here: chiefly c. 800 BCE–500 CE',eras:['greece','rome']},
{id:'medieval',zh:'中世纪',en:'Middle Ages',dateZh:'约500—1500',dateEn:'c. 500–1500',eras:['late','carolingian','medieval','frontiers']},
{id:'early',zh:'近代早期',en:'Early modern period',dateZh:'约1500—1800',dateEn:'c. 1500–1800',eras:['renaissance','reformation','dynasties']},
{id:'modern',zh:'近现代',en:'Modern & contemporary',dateZh:'约1800—今天',dateEn:'c. 1800–present',eras:['revolution','industry','war','postwar']}
];
const periodFor=id=>PERIODS.find(p=>p.eras.includes(id));
const periodLabel=id=>({late:L('古代晚期 → 中世纪早期','Late Antiquity → Early Middle Ages'),carolingian:L('中世纪早期','Early Middle Ages'),medieval:L('中世纪盛期 → 晚期','High → Late Middle Ages'),frontiers:L('中世纪 → 近代早期','Middle Ages → Early modern'),renaissance:L('中世纪晚期 → 近代早期','Late Middle Ages → Early modern'),revolution:L('近代早期 → 近现代','Early modern → Modern'),industry:L('近代早期 → 近现代','Early modern → Modern')}[id]||L(periodFor(id).zh,periodFor(id).en));
for(const e of ERAS){const en=ERA_EN[e.id];['date','title','question','summary','next'].forEach((key,i)=>{const zh=e[key];Object.defineProperty(e,key,{get:()=>L(zh,en[i])});});}
for(const s of SITES){for(const key of ['name','city','period','why','see','question','relation']){const zh=s[key],en=key==='name'?s.nameEn:key==='relation'?RELATIONS_EN[zh]:SITE_EN[s.id][key];Object.defineProperty(s,key,{get:()=>L(zh,en)});}}
